/* MedicCare.module.css */

.root {
  --vt-surface: #FFFFFF;
  --vt-surface-2: #F9F9F9;
  --vt-surface-deep: #000000;
  --vt-ink: #000000;
  --vt-ink-soft: #717275;
  --vt-on-deep: #FFFFFF;
  --vt-accent: #247cff;
  --vt-on-accent: #FFFFFF;
  --vt-accent-ink: #0d47a1;
  --vt-accent-on-deep: #247cff;
  --vt-line: #eaeaea;

  font-family: 'Open Sans', sans-serif;
  background: var(--vt-surface);
  color: var(--vt-ink);
  padding-top: 94px;
}

/* NAVIGATION */
.nav {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: var(--vt-surface);
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  z-index: 100;
  padding-top: 20px;
  padding-bottom: 20px;
}

.navIn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
  gap: 30px;
}

.navLinksLeft,
.navLinksRight {
  display: flex;
  align-items: center;
  gap: 1.5rem;
  flex: 1;
}

.navLinksLeft {
  justify-content: flex-end;
}

.navLinksRight {
  justify-content: flex-start;
}

.nav a {
  color: var(--vt-ink-soft);
  font-weight: 600;
  font-size: 16px;
  text-decoration: none;
  transition: color 0.3s;
  white-space: nowrap;
}

.nav a:hover,
.nav a:focus {
  color: var(--vt-ink);
}

.logo {
  display: block;
  text-align: center;
  margin: 0 30px;
  flex-shrink: 0;
}

.brand {
  display: block;
}

/* HERO */
.hero {
  padding-top: 0;
}

.heroInner {
  position: relative;
  overflow: hidden;
  height: 580px;
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

.heroSlides {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  height: 100%;
  scrollbar-width: none;
}

.heroSlides::-webkit-scrollbar {
  display: none;
}

.heroImage {
  flex: 0 0 100%;
  width: 100%;
  height: 100%;
  object-fit: cover;
  scroll-snap-align: start;
}

.heroText {
  position: absolute;
  bottom: 0;
  right: 0;
  background: var(--vt-surface);
  padding: 1.5rem 2.5rem;
  width: 50%;
  z-index: 2;
  box-sizing: border-box;
}

.heroText h1 {
  font-size: 48px;
  font-weight: 700;
  color: var(--vt-ink);
  margin: 0 0 0.5rem 0;
  line-height: 1.2;
}

.heroText h1 span {
  color: var(--vt-accent);
}

.heroText p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  letter-spacing: 0.5px;
  margin-bottom: 1.5rem;
}

.heroLinks {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1.5rem;
}

.customLink {
  display: inline-block;
  border: 1px solid var(--vt-line);
  color: var(--vt-accent);
  font-weight: 600;
  line-height: 40px;
  padding: 0 30px;
  text-transform: uppercase;
  text-decoration: none;
  transition: background-color 0.3s, color 0.3s;
}

.customLink:hover {
  background: var(--vt-line);
  color: var(--vt-accent);
}

.contactPhone {
  font-weight: 600;
  color: var(--vt-ink);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* SECTIONS */
.sectionPadding {
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.container {
  max-width: 1140px;
  margin: 0 auto;
  padding: 0 15px;
}

/* ABOUT */
.aboutRow {
  display: flex;
  justify-content: center;
}

.aboutText {
  max-width: 800px;
  text-align: center;
}

.aboutText h2 {
  font-size: 36px;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 1rem;
}

.aboutText p {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
  line-height: 1.7;
  letter-spacing: 0.5px;
}

/* GALLERY */
.galleryRow {
  display: flex;
  flex-wrap: wrap;
}

.galleryItem {
  flex: 0 0 50%;
}

.galleryItem img {
  width: 100%;
  display: block;
  height: auto;
}

/* TIMELINE */
.timelineTitle {
  text-align: center;
  font-size: 36px;
  font-weight: 700;
  color: var(--vt-ink);
  margin-bottom: 4rem;
}

.timeline {
  position: relative;
}

.timeline::before {
  content: "";
  position: absolute;
  top: 37px;
  left: 50%;
  width: 0;
  border-left: 1px solid var(--vt-line);
  height: 85%;
  z-index: 1;
  transform: translateX(-50%);
}

.timelineNodes {
  position: relative;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 4rem;
}

.timelineContent {
  width: 45%;
  background: var(--vt-surface);
  border-radius: 0 0 0.25rem 0.25rem;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
  position: relative;
}

.timelineContent h3 {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 10px 30px;
  margin: 0;
  font-size: 26px;
  font-weight: 600;
  border-radius: 0.25rem 0.25rem 0 0;
  position: relative;
}

.timelineContent h3::after {
  content: "";
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 0;
  height: 0;
}

.timelineContent p {
  padding: 10px 30px;
  margin: 0;
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
}

.timelineIcon {
  width: 10%;
  display: flex;
  justify-content: center;
  position: relative;
  z-index: 2;
}

.timelineIcon span {
  display: block;
  width: 80px;
  height: 80px;
  background: var(--vt-surface);
  border-radius: 50%;
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.175);
}

.timelineDate {
  width: 45%;
  padding: 1rem 0;
}

.timelineDate time {
  font-size: 16px;
  font-weight: 600;
  color: var(--vt-ink-soft);
}

/* Odd nodes */
.timelineNodes:nth-child(odd) .timelineContent {
  text-align: right;
}

.timelineNodes:nth-child(odd) .timelineContent h3::after {
  left: 100%;
  border-left: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNodes:nth-child(odd) .timelineDate {
  text-align: left;
}

/* Even nodes */
.timelineNodes:nth-child(even) {
  flex-direction: row-reverse;
}

.timelineNodes:nth-child(even) .timelineContent {
  text-align: left;
}

.timelineNodes:nth-child(even) .timelineContent h3::after {
  right: 100%;
  border-right: 10px solid var(--vt-surface-deep);
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
}

.timelineNodes:nth-child(even) .timelineDate {
  text-align: right;
}

/* FOOTER */
.footer {
  background: var(--vt-surface-2);
  padding-top: 7rem;
  padding-bottom: 7rem;
}

.footerRow {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 30px;
}

.footerColHours,
.footerColClinic,
.footerColSocial,
.footerColCopyright {
  flex: 1 1 0;
  min-width: 0;
}

.footerColHours {
  flex-basis: 41.666%;
}

.footerColClinic {
  flex-basis: 16.666%;
}

.footerColSocial {
  flex-basis: 25%;
}

.footerColCopyright {
  flex-basis: 25%;
}

.footer h5 {
  font-size: 24px;
  font-weight: 600;
  color: var(--vt-ink);
  margin-bottom: 1rem;
}

.footer p,
.footer a {
  color: var(--vt-ink-soft);
  font-size: 18px;
  font-weight: 300;
}

.footer a {
  text-decoration: none;
  transition: color 0.3s;
}

.footer a:hover {
  color: var(--vt-accent);
}

.socialLinks {
  display: flex;
  gap: 15px;
}

.copyright {
  font-size: 16px;
}

/* RESPONSIVE */
@media (max-width: 991px) {
  .root {
    padding-top: 74px;
  }

  .nav {
    padding-top: 10px;
    padding-bottom: 10px;
  }

  .navIn {
    padding: 10px 15px;
    gap: 15px;
  }

  .heroInner {
    height: auto;
    overflow: visible;
  }

  .heroSlides {
    height: auto;
  }

  .heroImage {
    height: auto;
  }

  .heroText {
    position: relative;
    bottom: 100px;
    left: 0;
    width: auto;
    margin-bottom: -100px;
    padding: 2rem;
  }

  .sectionPadding {
    padding-top: 5rem;
    padding-bottom: 5rem;
  }

  .aboutText h2 {
    font-size: 32px;
  }

  .timelineTitle {
    font-size: 32px;
  }

  .timelineContent h3 {
    font-size: 24px;
  }
}

@media (max-width: 767px) {
  .navIn {
    flex-wrap: wrap;
    justify-content: center;
  }

  .navLinksLeft,
  .navLinksRight {
    flex: 1 1 100%;
    justify-content: center;
    gap: 1rem;
    padding: 5px 0;
  }

  .logo {
    order: -1;
    margin: 0;
    width: 100%;
    text-align: center;
    padding: 10px 0;
  }

  .heroText {
    padding: 1.5rem;
    bottom: 80px;
    margin-bottom: -80px;
  }

  .heroText h1 {
    font-size: 38px;
  }

  .galleryRow {
    flex-direction: column;
  }

  .galleryItem {
    flex: 0 0 100%;
  }

  .timeline::before {
    left: 33px;
    top: 60px;
    height: 90%;
    transform: none;
  }

  .timelineNodes {
    flex-direction: column;
    margin-left: 60px;
    margin-bottom: 3rem;
  }

  .timelineNodes:nth-child(even) {
    flex-direction: column;
  }

  .timelineContent,
  .timelineDate {
    width: 100%;
    text-align: left;
  }

  .timelineNodes:nth-child(odd) .timelineContent,
  .timelineNodes:nth-child(even) .timelineContent {
    text-align: left;
  }

  .timelineNodes:nth-child(odd) .timelineDate,
  .timelineNodes:nth-child(even) .timelineDate {
    text-align: left;
  }

  .timelineIcon {
    position: absolute;
    left: -60px;
    top: 0;
    width: 50px;
  }

  .timelineIcon span {
    width: 50px;
    height: 50px;
  }

  .timelineContent h3::after {
    right: 100%;
    left: auto;
    border-right: 10px solid var(--vt-surface-deep);
    border-left: 0;
    border-top: 10px solid transparent;
    border-bottom: 10px solid transparent;
  }

  .footerRow {
    flex-direction: column;
    gap: 2rem;
  }

  .footerColHours,
  .footerColClinic,
  .footerColSocial,
  .footerColCopyright {
    flex-basis: auto;
    width: 100%;
  }
}

@media (max-width: 575px) {
  .timeline::before {
    left: 57px;
  }

  .timelineNodes {
    margin-left: 70px;
  }

  .timelineIcon {
    left: -70px;
  }

  .timelineIcon span {
    width: 70px;
    height: 70px;
  }
}

@media (max-width: 480px) {
  .heroText {
    padding: 1rem;
  }

  .heroLinks {
    gap: 1rem;
  }

  .customLink {
    font-size: 12px;
    line-height: 30px;
    padding: 0 25px;
  }

  .contactPhone {
    font-size: 12px;
  }
}

@media (max-width: 360px) {
  .timeline::before {
    left: 42px;
  }

  .timelineNodes {
    margin-left: 55px;
  }

  .timelineIcon {
    left: -55px;
  }

  .timelineIcon span {
    width: 55px;
    height: 55px;
  }
}
